{"path": "bowling.py", "content": "class BowlingGame:
    def __init__(self):
        self.rolls = []
        self.frame = 0          # index of the current frame (0-9)
        self.first = None       # first roll of the current frame (frames 1-9)
        self.tenth = []         # rolls made in the tenth frame

    def _game_over(self):
        if self.frame < 9:
            return False
        if len(self.tenth) == 3:
            return True
        return len(self.tenth) == 2 and sum(self.tenth) < 10

    def roll(self, pins):
        if not isinstance(pins, int) or pins < 0:
            raise ValueError("Negative roll is invalid")
        if pins > 10:
            raise ValueError("Pin count exceeds pins on the lane")
        if self._game_over():
            raise IndexError("Cannot roll after game is over")

        if self.frame < 9:
            if self.first is None:
                if pins == 10:
                    self.frame += 1
                else:
                    self.first = pins
            else:
                if self.first + pins > 10:
                    raise ValueError("Pin count exceeds pins on the lane")
                self.frame += 1
                self.first = None
        else:
            t = self.tenth + [pins]
            if len(t) == 2 and t[0] < 10 and t[0] + t[1] > 10:
                raise ValueError("Pin count exceeds pins on the lane")
            if len(t) == 3 and t[0] == 10 and t[1] < 10 and t[1] + t[2] > 10:
                raise ValueError("invalid fill balls")
            self.tenth = t

        self.rolls.append(pins)

    def score(self):
        if not self._game_over():
            raise IndexError("Score cannot be taken until the end of the game")
        rolls = self.rolls
        total = 0
        i = 0
        for _ in range(10):
            if rolls[i] == 10:
                total += 10 + rolls[i + 1] + rolls[i + 2]
                i += 1
            elif rolls[i] + rolls[i + 1] == 10:
                total += 10 + rolls[i + 2]
                i += 2
            else:
                total += rolls[i] + rolls[i + 1]
                i += 2
        return total
